-- Fase 7b — Packs Pro: Andes, Cono Sur, México y Centroamérica, Caribe (docs/GeoSpeed_Plan_Competencia.md §9)
--
-- Decisiones de JuanJo (2026-10-23): incluidos en Pro con una partida de prueba gratis al día por pack (eso lo controla
-- la app); escala de cercanía de 400 km. El servidor ya estaba listo desde la 7a: mode_scale_km('andes'…) = 400, los
-- retos admiten esos modos, places.kind 'division' y la categoría 'divisions'. Esta migración solo siembra las divisiones
-- (con contorno) y las ciudades de los cuatro packs, generadas por scripts/build-pro-packs.mjs desde Natural Earth.
-- Idempotente: se aplica desde el SQL Editor (db push responde 403).
-- ════════════════════════════════════════════════════════════════════════════

-- Generado por scripts/build-pro-packs.mjs (packs Pro, Fase 7b). No editar a mano.
on conflict (id) do update set kind = excluded.kind, name = excluded.name, country = excluded.country, lat = excluded.lat, lon = excluded.lon;

delete from public.place_shapes where place_id like 'div:bo-%' or place_id like 'div:pe-%' or place_id like 'div:ec-%' or place_id like 'div:ve-%' or place_id like 'div:ar-%' or place_id like 'div:uy-%' or place_id like 'div:cl-%' or place_id like 'div:py-%' or place_id like 'div:cr-%' or place_id like 'div:ni-%' or place_id like 'div:sv-%' or place_id like 'div:gt-%' or place_id like 'div:hn-%' or place_id like 'div:mx-%' or place_id like 'div:bz-%' or place_id like 'div:pa-%' or place_id like 'div:ht-%' or place_id like 'div:do-%' or place_id like 'div:cu-%' or place_id like 'div:pr-%' or place_id like 'div:jm-%';
